-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 18;
delete from public.abdeckung where thema_id = 18;
delete from public.pruef_einheiten where thema_id = 18;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (7932, 18, 'CO2-Bepreisung bzw. Emissionshandel für Verkehr und Gebäude stärken (Bund)', 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'bund', null, true, 'blind'),
  (7933, 18, 'Verbindliche Sektorziele und Nachsteuerungspflicht im Klimaschutzgesetz (Bund)', 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'offen', null, 'bund', null, true, 'blind'),
  (7934, 18, 'Ausbau erneuerbarer Strom- und Wärmeversorgung fördern (Bund)', 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'belegt', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'bund', null, true, 'blind'),
  (7935, 18, 'Abscheidung und Speicherung von CO2 (CCS/CCU) ermöglichen und fördern (Bund)', 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'gemischt', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'bund', null, true, 'blind'),
  (7936, 18, 'Kohleausstieg aussetzen oder Abschaltung von Kohlekraftwerken aufschieben (Bund)', 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'belegt', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'bund', null, true, 'blind'),
  (7937, 18, 'Nationalen CO2-Preis abschaffen (Bund)', 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'bund', null, true, 'blind'),
  (7938, 18, 'CO2-Flottenvorgaben für Neuwagen (Verbrenner-Aus 2035) aufheben (Bund)', 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'offen', null, 'bund', null, true, 'blind'),
  (7939, 18, 'Heizungsvorgaben im Gebäudeenergiegesetz abschaffen (Bund)', 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'offen', null, 'bund', null, true, 'blind'),
  (7940, 18, 'Bundesförderung für Stadtgrün, Entsiegelung und hitzeangepasste Städte (Bund)', 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'bund', null, true, 'blind'),
  (7941, 18, 'Allgemeine Zusage zu Begrünung und Entsiegelung ohne konkretes Instrument (Bund)', 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'bund', null, true, 'blind'),
  (7942, 18, 'Bundesmittel für Hochwasserschutz: Deiche, Rückhalteräume und Auen (Bund)', 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'belegt', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'bund', null, true, 'blind'),
  (8453, 18, 'Begrünungspflicht bzw. Mindestgrünanteil für Neubauten (Dach, Fassade, Freifläche) (Land)', 'Per Bauordnung umsetzbar; Gründächer und -fassaden senken Oberflächentemperaturen um rund 2 °C. Dagegen: Wirkung auf die Lufttemperatur auf Straßenniveau ist gering belegt und betrifft nur Neubauten, also langsam.', 'gemischt', 'https://research.bangor.ac.uk/en/publications/how-effective-is-greening-of-urban-areas-in-reducing-human-exposu/', 'land', null, true, 'blind'),
  (8454, 18, 'Straßenbäume in großer Zahl neu pflanzen (Land)', 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'land', null, true, 'blind'),
  (8455, 18, 'Bestand an Stadtbäumen und Grünflächen schützen, bewässern und pflegen (Land)', 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'land', null, true, 'blind'),
  (8456, 18, 'Neue Grünflächen, Stadtwald und hitzeangepasste Quartiere schaffen und fördern (Land)', 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'land', null, true, 'blind'),
  (8457, 18, 'Allgemeine Zusage zu Klimaanpassung, Stadtgrün oder Starkregenvorsorge ohne konkretes Instrument (Land)', 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'land', null, true, 'blind'),
  (8458, 18, 'Kaltluftschneisen und große Freiflächen in der Stadt von Bebauung freihalten (Land)', 'Kaltluft aus Freiflächen entlastet überhitzte Stadtteile in heißen Nächten, Fachrichtlinien empfehlen den Erhalt von Luftleitbahnen; planerisch umsetzbar. Dagegen: wirkt nur bei windschwachen Nächten und in begrenzter Reichweite.', 'belegt', 'https://www.baulinks.de/webplugin/2024/0925.php4', 'land', null, true, 'blind'),
  (8459, 18, 'Baulichen Hitzeschutz an Schulen, öffentlichen Gebäuden und Einrichtungen fördern und umsetzen (Land)', 'Verschattung, Nachtlüftung und passive Kühlung senken Innentemperaturen in Modellstudien deutlich. Dagegen: Nachrüstung ist teuer und dauert, bei künftig stärkerer Hitze reichen passive Maßnahmen allein teils nicht.', 'gemischt', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'land', null, true, 'blind'),
  (8460, 18, 'Hitzeschutzpläne und -konzepte für gefährdete Gruppen und Einrichtungen umsetzen (Land)', 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'belegt', 'https://www.santepubliquefrance.fr/en/node/37874', 'land', null, true, 'blind'),
  (8461, 18, 'Trinkbrunnen und Trinkwasserspender im öffentlichen Raum ausbauen (Land)', 'Kostengünstig und schnell umsetzbar, erleichtert ausreichendes Trinken bei Hitze. Dagegen: lindert nur Folgen, eine gesundheitliche Wirkung öffentlicher Trinkbrunnen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8462, 18, 'Öffentliche Abkühlungsmöglichkeiten schaffen: Badestellen, Planschen und Brunnen (Land)', 'Bietet Abkühlung an heißen Tagen, besonders ohne Freibad in der Nähe. Dagegen: lindert nur Folgen, Wasserqualität und Badesicherheit erfordern Aufwand; Wirkung auf Gesundheit kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8463, 18, 'Spielplätze und öffentliche Wasserflächen mit Sonnensegeln verschatten (Land)', 'Schatten senkt die gefühlte Temperatur vor Ort deutlich und ist günstig umsetzbar. Dagegen: wirkt nur punktuell an einzelnen Orten, Gesundheitswirkung kaum gesondert untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8464, 18, 'Verbindliches Netto-Null-Ziel oder Flächenkontingente für Neuversiegelung festlegen (Land)', 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'gemischt', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'land', null, true, 'blind'),
  (8465, 18, 'Vorrang für Innenentwicklung, Flächenrecycling und Freiflächenschutz ohne verbindliche Mengenvorgabe (Land)', 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'gemischt', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'land', null, true, 'blind'),
  (8466, 18, 'Entsiegelung öffentlicher und privater Flächen fördern oder vorschreiben (Land)', 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'belegt', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'land', null, true, 'blind'),
  (8467, 18, 'Schwammstadt: dezentrale Regenwasserbewirtschaftung, Abkopplung und Rückhalt in Siedlungen ausbauen (Land)', 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'belegt', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'land', null, true, 'blind'),
  (8468, 18, 'Landesberatungsstelle für Regenwasserbewirtschaftung besser ausstatten (Land)', 'Beratung und Koordination können den Umbau zur Schwammstadt beschleunigen und sind günstig umsetzbar. Dagegen: Die Stelle baut selbst kaum etwas, ihr eigener Beitrag zur Entsiegelung ist nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8469, 18, 'Regenwassernutzung vorschreiben oder erleichtern (Bauordnung, Bewässerung, Regentonnen) (Land)', 'Per Bauordnung oder Vorgabe leicht umsetzbar, hält etwas Regenwasser vor Ort. Dagegen: Speichervolumen ist klein, bei Starkregen ist der Speicher schnell voll; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8470, 18, 'Kein neues Baurecht für Bürogebäude, um Versiegelung zu vermeiden (Land)', 'Verhindert einzelne Neuversiegelungen. Dagegen: Bürobauten sind ein kleiner Teil der Neuversiegelung, bestehendes Baurecht bleibt; die Wirkung ist nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8471, 18, 'Retentionsräume, Auen und Deichrückverlegungen für den Hochwasserschutz schaffen oder sichern (Land)', 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'belegt', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'land', null, true, 'blind'),
  (8472, 18, 'Deiche, Dünen und Hochwasserschutzanlagen sanieren und modernisieren (Land)', 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'belegt', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'land', null, true, 'blind'),
  (8473, 18, 'Keine neuen Baugebiete und Bebauung in Überschwemmungsgebieten zulassen (Land)', 'Verzicht auf Bebauung in Überschwemmungsflächen gilt Fachbehörden als wirksamste Vermeidung von Hochwasserschäden. Dagegen: Rahmen setzt das Bundesrecht (Ausnahmen im WHG), Länder können nur Planung und Ausnahmepraxis verschärfen; Bestand bleibt.', 'belegt', 'https://www.lfu.bayern.de/wasser/hw_handlungsfelder/vermeidung/index.htm', 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 18 and id not in (7932, 7933, 7934, 7935, 7936, 7937, 7938, 7939, 7940, 7941, 7942, 8453, 8454, 8455, 8456, 8457, 8458, 8459, 8460, 8461, 8462, 8463, 8464, 8465, 8466, 8467, 8468, 8469, 8470, 8471, 8472, 8473);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (7943, 18, 11, null, 'Flächendeckende Pflichtversicherung für Elementarschäden einführen', '{1806}', null, 3, 2, null, 'Setzt direkt an der Versicherungslücke an: Frankreich erreicht mit verpflichtender Deckung rund 98 %, Deutschland rund 50 %. Verfassungsrechtlich laut Justizministerkonferenz möglich; Prämien in Risikogebieten bleiben strittig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', 'https://www.bundestag.de/dokumente/textarchiv/2024/kw11-pa-recht-elementarschadenversicherung-991898', 'belegt', '2026-10-04', false, true, 'blind'),
  (7944, 18, 11, null, 'Küsten- und Hochwasserschutz priorisieren und von der Ausgleichspflicht für solche Maßnahmen wegkommen', '{1805}', null, 1, 2, null, 'Weniger Ausgleichspflichten können Hochwasserschutzbauten beschleunigen. Dagegen: Kein zusätzliches Geld oder Vorhaben, Bauen in Überschwemmungsgebieten bleibt unberührt, EU-Naturschutzrecht begrenzt den Spielraum.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7945, 18, 11, null, 'Flächenversiegelung reduzieren und Flächen klüger nutzen', '{1804}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=26', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7946, 18, 11, null, 'Städte und Gemeinden bei Wassermanagement und verstärkter Begrünung unterstützen', '{1803}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7947, 18, 11, null, 'CO2-Bepreisung zum Leitinstrument ausbauen, Einnahmen zurückgeben', '{1801,1802}', 7932, 1, 2, null, 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7948, 18, 11, null, 'Heizungsgesetz abschaffen, stattdessen technologieoffen emissionsarme Wärme fördern', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7949, 18, 11, null, 'Verbrenner-Verbot rückgängig machen', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7950, 18, 11, null, 'Kein weiteres endgültiges Abschalten von Kohlekraftwerken, bevor Ersatz gebaut ist', '{1801,1802}', 7936, 0, 2, null, 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=21', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7951, 18, 11, null, 'Moorschutz intensivieren und Anreize für Wiedervernässung geben', '{1801,1802}', null, 1, 2, null, 'Entwässerte Moore verursachen rund 7,5 % der deutschen Emissionen; Wiedervernässung senkt sie deutlich. Dagegen: Umsetzung braucht Einigung mit Eigentümern und Zeit; die Wirkung auf Hitze bleibt gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', 'https://www.bundesumweltministerium.de/faq/warum-ist-die-wiedervernaessung-von-mooren-so-wichtig', 'belegt', '2026-10-04', false, true, 'blind'),
  (7952, 18, 11, null, 'Rahmenbedingungen für Kohlenstoffabscheidung, -nutzung und -speicherung samt Transportinfrastruktur schaffen', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7953, 18, 12, null, 'Städtebauförderung zur Klimaanpassung: Begrünung, Entsiegelung (Schwammstadt) und kühlende öffentliche Räume in Städten.', '{1803}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7954, 18, 12, null, 'Vorsorge gegen Klimafolgen wie Hitzewellen im Bevölkerungsschutz stärken.', '{1801}', null, 1, 3, null, 'Vorsorge gegen Hitzewellen im Bevölkerungsschutz ist sinnvoll und umsetzbar. Dagegen: Die Zusage nennt kein konkretes Instrument, daher ist die Wirkung kaum abschätzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=46', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7955, 18, 12, null, 'Kommunale Wärmepläne für klimaneutrale Wärmeversorgung fördern.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7956, 18, 12, null, 'Mittel aus Aktionsprogramm Natürlicher Klimaschutz flächendeckend einsetzen, um Wälder, Moore, Flussauen und Stadtgrün zu schützen.', '{1801,1802,1803}', null, 1, 3, null, 'Das bestehende Förderprogramm stärkt Senken und Stadtgrün und ist finanziert. Dagegen: Die Mittel verteilen sich breit, der Beitrag zur Kühlung von Städten und zur Hitzevermeidung bleibt gering.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7957, 18, 12, null, 'Windkraft und Fotovoltaik konsequent ausbauen und mit Speichern einbinden.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7958, 18, 13, null, 'Europäischen Emissionshandel für Verkehr und Gebäude unterstützen und den CO₂-Preis als zentralen Hebel stärken', '{1801,1802}', 7932, 1, 2, null, 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=38', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7959, 18, 13, null, 'Sektorverantwortung im Klimaschutzgesetz stärken, bei Zielverfehlung verbindlich nachsteuern', '{1801,1802}', 7933, 1, 3, null, 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=39', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7960, 18, 13, null, 'Alle verbliebenen Kohlekraftwerke ab 2030 nicht mehr befeuern, Kohleförderung beenden, fossiles Gas schrittweise reduzieren', '{1801,1802}', null, 1, 2, null, 'Ein Kohleausstieg senkt die Emissionen des Stromsektors deutlich (Studien). Dagegen: Ersatzkraftwerke und Versorgungssicherheit bis 2030 sind ungeklärt, und die Wirkung auf Hitze in Deutschland ist gering und verzögert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7961, 18, 13, null, 'Förderung für fossilfreie Heizungen und Wärmenetze ausbauen, Energieberatung ausbauen', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7962, 18, 13, null, 'Hochwasserschutz mit den Ländern verbessern: natürliche Überschwemmungsräume, Auen mehr Raum, Deiche und Rückhaltesysteme, beschleunigte Umsetzung', '{1805}', 7942, 2, 3, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-04', false, true, 'blind'),
  (7963, 18, 13, null, 'Städte gegen Hitzewellen und Starkregen schützen: mehr Entsiegelung, Frischluftschneisen, Gebäude- und Stadtgrün, Trinkbrunnen, Schwammstadt', '{1802,1803,1804}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7964, 18, 13, null, 'Versicherungsschutz gegen Elementarschäden sozialverträglich ausweiten', '{1806}', null, 2, 2, null, 'Setzt an der Versicherungslücke an; Erfahrungen anderswo zeigen, dass verbindliche Modelle die Deckung stark erhöhen. Dagegen: Ohne bestimmtes Instrument (Pflicht oder Angebotsmodell) ist der Umfang der Verbesserung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://www.bundestag.de/dokumente/textarchiv/2024/kw11-pa-recht-elementarschadenversicherung-991898', 'belegt', '2026-10-04', false, true, 'blind'),
  (7965, 18, 13, null, 'Nationalen Hitzeschutzplan ausbauen und Hitzeaktionspläne in allen Kommunen', '{1802}', null, 3, 2, null, 'Hitzeschutzpläne senkten die hitzebedingte Übersterblichkeit in Europa um rund 25 %. Dagegen: Pläne in allen Kommunen kann der Bund nicht vorschreiben, nur fördern und mit Ländern vereinbaren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12724396/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7966, 18, 13, null, 'Flächenverbrauch mit neuen Instrumenten (Flächenzertifikatehandel, Baulandabgabemodell) bis 2030 auf 30 Hektar pro Tag senken', '{1804}', null, 2, 2, null, 'Ein Planspiel mit 87 Kommunen zeigte, dass Flächenzertifikate Neuversiegelung wirksam begrenzen können. Dagegen: Reale Erfahrungen fehlen, und die Einführung braucht neue Bundesregeln und Akzeptanz der Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://www.umweltbundesamt.de/themen/flaechenzertifikatehandel-flaechenverbauchsziele', 'offen', '2026-10-04', false, true, 'blind'),
  (7967, 18, 14, null, 'Einheitlicher europäischer Emissionshandel als Leitinstrument der Klimapolitik, mit global angestrebtem Preis für Treibhausgase', '{1801,1802}', null, 1, 1, null, 'Emissionshandel senkt Emissionen nachweislich. Dagegen: Ein einheitlicher EU-Handel hängt von EU-Entscheidungen ab, ein globaler Preis von anderen Staaten; die Wirkung auf Hitze in Deutschland ist gering.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7968, 18, 14, null, 'Nationales Klimaneutralitätsziel 2045 im Klimaschutzgesetz durch das europäische Ziel 2050 ersetzen', '{1801,1802}', null, 0, 1, null, 'Ein späteres Klimaneutralitätsziel bremst Emissionsminderung und hilft nicht gegen Hitze. Rechtlich heikel, weil das Bundesverfassungsgericht einen ausreichenden Reduktionspfad verlangt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7969, 18, 14, null, 'Abscheidung und Speicherung von Treibhausgasen (CCS/CCU) diskriminierungsfrei als Klimaschutz-Option ermöglichen', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7970, 18, 14, null, 'Heizungsgesetz vollständig auslaufen lassen; stattdessen Zertifikatehandel', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7971, 18, 14, null, 'Faktisches Verbrenner-Verbot ab 2035 umgehend aufheben', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7972, 18, 14, null, 'Erneuerbare Energien ohne EEG-Subventionen für neue Anlagen vollständig in den Markt überführen', '{1801,1802}', null, 0, 2, null, 'Marktintegration kann Förderkosten senken; ohne Absicherung droht aber ein langsamerer Ausbau, der Emissionen weniger senkt. Ein Beitrag gegen Hitze ist nicht zu erwarten; EEG-Änderung möglich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7973, 18, 14, null, 'Bau neuer Kernkraftwerke und Wiederinbetriebnahme vorhandener rechtlich ermöglichen, ohne Subventionen', '{1801,1802}', null, 0, 1, null, 'Kernkraft ist emissionsarm, ohne Subventionen ist ein Neubau aber nicht absehbar; ob vorhandene Anlagen reaktiviert werden können, ist umstritten. In einer Wahlperiode ist keine Wirkung auf Emissionen zu erwarten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7974, 18, 15, null, 'Geplanten Ausstieg aus der Braunkohleverstromung nicht umsetzen, Kohlekraftwerke ausbauen.', '{1801,1802}', 7936, 0, 2, null, 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7975, 18, 15, null, 'Wiedereinstieg in die Kernenergie, bestehende Kraftwerke so schnell wie möglich wieder in Betrieb nehmen.', '{1801,1802}', null, 0, 1, null, 'Der zugleich geplante Ausbau von Kohlekraftwerken erhöht Emissionen. Eine Rückkehr zur Kernenergie wäre in einer Wahlperiode kaum wirksam, weil der Rückbau fortgeschritten ist und Betreiber eine Reaktivierung ablehnen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7976, 18, 15, null, 'Abgabe auf CO₂ abschaffen.', '{1801,1802}', 7937, 0, 2, null, 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7977, 18, 15, null, 'Verbot von Gas- und Ölheizungen aufheben.', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7978, 18, 15, null, 'Verbot des Verbrennungsmotors aufheben.', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7979, 18, 15, null, 'Weiteren Ausbau der Windenergie ablehnen.', '{1801,1802}', null, 0, 2, null, 'Ein Stopp des Windausbaus bremst die Verdrängung fossiler Stromerzeugung, die nachweislich Emissionen vermeidet, und hilft nicht gegen Hitze. Erfordert Änderungen an EEG und Planungsrecht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=81', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7980, 18, 15, null, 'Aus dem Pariser Klimaabkommen aussteigen.', '{1801,1802}', null, 0, 2, null, 'Der Austritt schwächt internationale Klimaschutzverpflichtungen und hilft nicht gegen Hitze. Rechtlich per Kündigung möglich; EU-Klimarecht bliebe bindend.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=80', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7981, 18, 16, null, 'Kitas und Schulen besser vor Hitzewellen schützen, Investitionsmittel dafür bereitstellen', '{1802}', null, 1, 2, null, 'Kinder leiden bei Hitze häufig gesundheitlich, Investitionen in Kitas und Schulen helfen ihnen. Dagegen: Die meisten Hitzetoten sind über 75; Kitas und Schulen sind Sache von Ländern und Kommunen, der Bund kann nur mitfinanzieren.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7982, 18, 16, null, 'Mehr öffentliche Parks und Grünflächen gegen die Hitze sowie öffentliche Wasserspender; Gebäude- und Flächenbegrünung ausweiten', '{1803,1802}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7983, 18, 16, null, 'Flächenentsiegelung vorantreiben, Städte zu Schwammstädten machen und vor Flutkatastrophen schützen', '{1804}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7984, 18, 16, null, 'Luftaustausch zwischen Stadt und Umland durch bessere Raumplanung verbessern', '{1803}', null, 2, 2, null, 'Kaltluftbahnen aus dem Umland verbessern die nächtliche Abkühlung von Städten. Dagegen: Die Planung liegt überwiegend bei Ländern und Kommunen, der Bund kann nur über Raumordnung und Baurecht beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.vdi.de/news/detail/lokale-kaltluft-in-staedten-ein-wichtiger-baustein-im-zuge-der-klimaanpassung', 'belegt', '2026-10-04', false, true, 'blind'),
  (7985, 18, 16, null, 'Klimaanpassung als Gemeinschaftsaufgabe von Bund, Ländern und Kommunen definieren, Katastrophenschutz massiv aufwerten', '{1801}', null, 2, 1, null, 'Eine Gemeinschaftsaufgabe würde dauerhafte Mischfinanzierung von Anpassung durch Bund und Länder ermöglichen. Dagegen: Grundgesetzänderung mit Zweidrittelmehrheiten nötig, Wirkung hängt von späteren Mitteln ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7986, 18, 16, null, 'Sektorziele im Klimaschutzgesetz wiederherstellen, verbindliche Ziele und Emissionsgrenzen', '{1801,1802}', 7933, 1, 3, null, 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7987, 18, 16, null, 'Emissionshandel für Wärme und Verkehr (ETS-2) ablehnen, stattdessen verbindliche Klimaziele und Emissionsgrenzen', '{1801,1802}', null, 1, 1, null, 'Verbindliche Ziele und Grenzen können Emissionen senken. Dagegen: Der EU-Emissionshandel für Wärme und Verkehr ist beschlossenes EU-Recht, das Deutschland nicht allein abwählen kann; Wirkung auf Hitze gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7988, 18, 17, null, 'Nationalen CO2-Preis abschaffen.', '{1801,1802}', 7937, 0, 2, null, 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7989, 18, 17, null, 'Verbrenner-Verbot zurücknehmen.', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7990, 18, 17, null, 'Heizungsgesetz sofort abschaffen und durch andere Regelungen ersetzen.', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7991, 18, 17, null, 'Bau von CCS- und CCU-Anlagen durch Superabschreibungen oder öffentliche Kredite fördern.', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7992, 18, 17, null, 'Repowering-Programm: alte Windanlagen durch neue ersetzen.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7993, 18, 17, null, 'Fernwärme ausbauen und auf erneuerbare Quellen umstellen, Geothermie-Ausbauziele anheben.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7994, 18, 17, null, 'Mittel für Auf- und Ausbau von Deichen und Dämmen bereitstellen, Folgen von Hochwasser abmildern.', '{1805}', 7942, 2, 3, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=20', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-04', false, true, 'blind'),
  (8474, 18, 11, 'BE', 'Mehr Straßenbäume, bis 2040 eine Million Bäume, um die Stadt gegen Hitze und Extremwetter widerstandsfähiger zu machen', '{1803}', 8454, 2, 2, null, 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8475, 18, 11, 'BE', 'Hitzeschutz von Anfang an in Planung und Bau integrieren, besonders Dach- und Fassadenbegrünung bei öffentlichen Gebäuden', '{1803}', 8459, 2, 2, null, 'Verschattung, Nachtlüftung und passive Kühlung senken Innentemperaturen in Modellstudien deutlich. Dagegen: Nachrüstung ist teuer und dauert, bei künftig stärkerer Hitze reichen passive Maßnahmen allein teils nicht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8476, 18, 11, 'BE', 'Mehr Verschattung auf Spielplätzen, vor allem durch Sonnensegel, insbesondere in Neubaugebieten', '{1803}', 8463, 1, 3, null, 'Schatten senkt die gefühlte Temperatur vor Ort deutlich und ist günstig umsetzbar. Dagegen: wirkt nur punktuell an einzelnen Orten, Gesundheitswirkung kaum gesondert untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8477, 18, 11, 'BE', 'Neuer Stadtwald auf Teilen des Tempelhofer Feldes, der das Stadtklima verbessern soll', '{1803}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8478, 18, 11, 'BE', 'Mehr Trinkbrunnen, in Hitzeperioden zusätzlich temporäre Wasserspender und mobile Trinkstationen', '{1803}', 8461, 1, 3, null, 'Kostengünstig und schnell umsetzbar, erleichtert ausreichendes Trinken bei Hitze. Dagegen: lindert nur Folgen, eine gesundheitliche Wirkung öffentlicher Trinkbrunnen ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=81', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8479, 18, 11, 'BE', 'Schulhöfe, Kitagelände und Sportanlagen entsiegeln, begrünen und mit Wasserspeicherung ausstatten', '{1804}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=81', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8480, 18, 11, 'BE', 'Berlin zur Schwammstadt entwickeln: Regenwasser dezentral nutzen, Speicher ausbauen, Mischwassereinleitungen verringern', '{1804,1803}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=82', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8481, 18, 11, 'MV', 'Weiterentwicklung von Hitzeschutzkonzepten zum Schutz gefährdeter Gruppen bei Hitzetagen.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=82', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8482, 18, 11, 'MV', 'Stopp des Flächenfraßes; Vorrang effizienter Flächennutzung bei der Planung erneuerbarer Energien.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=119', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8483, 18, 11, 'MV', 'Sicherung und Modernisierung von Deichen, Dünen und Hochwasserschutzanlagen.', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=93', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8484, 18, 11, 'MV', 'Unterstützung regionaler Projekte für Hochwasser- und Küstenschutz zusammen mit Kommunen und Landnutzern.', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=93', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8485, 18, 11, 'MV', 'Aktionsplan, der Hochwasserschutz durch Gewässer-Renaturierung voranbringt.', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=93', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8486, 18, 11, 'ST', 'Hitzeschutz als Förderaspekt in der Städtebauförderung stärken; Maßnahmen zur Wasserspeicherung in Stadtquartieren unterstützen', '{1803,1804}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8487, 18, 11, 'ST', 'Flächenverbrauch begrenzen: Mehrfachnutzung versiegelter Flächen und Reaktivierung von Brachflächen fördern; Förderkulisse für Entsiegelung eröffnen', '{1804,1803}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8488, 18, 11, 'ST', 'Deiche zurückverlegen, wo eine Kosten-Nutzen-Abschätzung sinnvoll erscheint', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8489, 18, 12, 'BE', 'Hotspots mit Hitze- und Luftbelastung entsiegeln oder begrünen, etwa mit einem Tiny Forest', '{1803,1804}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8490, 18, 12, 'BE', 'Straßenbaumstandorte erhalten, Baumscheiben bis 2027 bepflanzen und neue Baumstandorte schaffen', '{1803}', 8454, 2, 2, null, 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8491, 18, 12, 'BE', 'Schutz älterer Bäume wegen ihrer Schattenwirkung verstärken', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8492, 18, 12, 'BE', 'Bezirksämter finanziell und personell für die naturnahe Pflege von Parks und Grünflächen ausstatten', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8493, 18, 12, 'BE', 'Zugang zu Wasser mit Planschen und Brunnen verbessern, durch die Berliner Wasserbetriebe', '{1803}', 8462, 1, 2, null, 'Bietet Abkühlung an heißen Tagen, besonders ohne Freibad in der Nähe. Dagegen: lindert nur Folgen, Wasserqualität und Badesicherheit erfordern Aufwand; Wirkung auf Gesundheit kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8494, 18, 12, 'BE', 'Mehr Regenwasser von der Kanalisation abkoppeln und vor Ort versickern lassen', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=23', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8495, 18, 12, 'BE', 'Abkopplung von Regenwasser per Gesetz verbindlich machen, grundstücksübergreifend', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=23', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8496, 18, 12, 'BE', 'Bei der Entwicklung von Wohnflächen bereits versiegelte Flächen vorrangig nutzen', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=18', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8497, 18, 12, 'MV', 'Reduzierung der weiteren Flächenversiegelung; ortstypische Innenentwicklung soll Vorrang vor neuen Baugebieten haben', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=87', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8498, 18, 12, 'MV', 'Blau-grüne Stadtentwicklung mit Wasserflächen und Bäumen unterstützen, die das innerstädtische Klima verbessern', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=87', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8499, 18, 12, 'MV', 'Alle zusammenhängend bebauten Gebiete an Küste und in Flusseinzugsgebieten vor Hochwasser schützen', '{1805}', null, 2, 1, null, 'Schutzanlagen für bebaute Gebiete mindern Hochwasserschäden wirksam. Dagegen: Schutz aller bebauten Gebiete ist sehr teuer, Finanzierung und Zeitrahmen sind offen; die Bebauung gefährdeter Flächen bleibt bestehen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=86', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
