  (8502, 18, 12, 'ST', 'Unterstützung der Kommunen bei Hitzeaktionsplänen und beim Schutz innerörtlicher Grünflächen', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8503, 18, 12, 'ST', 'Ausbau des Wasserrückhalts in der Fläche durch Versickerung und Schwammstadtkonzepte', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8504, 18, 12, 'ST', 'Vorrang für Flächenrecycling vor weiterer Versiegelung', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8505, 18, 12, 'ST', 'Systematische Weiterentwicklung und finanzielle Absicherung der Starkregenvorsorge', '{1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8506, 18, 12, 'ST', 'Abschluss der Sanierung und Sicherung der Deiche', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8507, 18, 12, 'ST', 'Schaffung oder Reaktivierung von Retentionsräumen und Rückhalteflächen', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8508, 18, 12, 'ST', 'Frühwarnsysteme, Pegeltechnik sowie Hochwasser- und Starkregenkarten für die Vorsorge in Kommunen', '{1805}', null, 1, 3, null, 'Warnsysteme und Gefahrenkarten helfen, bewegliche Werte zu sichern, und können Bauleitplanung lenken. Dagegen: Gebäudeschäden bleiben weitgehend, und die Bebauung gefährdeter Flächen wird nicht direkt begrenzt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', null, 'gemischt', '2026-10-10', false, true, 'blind'),
  (8509, 18, 13, 'BE', 'Eine Million Bäume pflanzen, vorrangig in Hitze-Hotspots, auf stark versiegelten Flächen und in dicht bebauten Kiezen; Baumpflanzungsgesetz umsetzen.', '{1803}', 8454, 2, 2, null, 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=42', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8510, 18, 13, 'BE', 'Gebäudekühlung über klimafreundliche Lüftungstechnik und Verdunstungskühlung statt üblicher Klimaanlagen; in öffentlichen Einrichtungen Vorrang.', '{1803}', 8459, 2, 2, null, 'Verschattung, Nachtlüftung und passive Kühlung senken Innentemperaturen in Modellstudien deutlich. Dagegen: Nachrüstung ist teuer und dauert, bei künftig stärkerer Hitze reichen passive Maßnahmen allein teils nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=16', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8511, 18, 13, 'BE', 'Kaltluftschneisen erhalten und, wo möglich, ausbauen.', '{1803}', 8458, 2, 3, null, 'Kaltluft aus Freiflächen entlastet überhitzte Stadtteile in heißen Nächten, Fachrichtlinien empfehlen den Erhalt von Luftleitbahnen; planerisch umsetzbar. Dagegen: wirkt nur bei windschwachen Nächten und in begrenzter Reichweite.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=22', 'https://www.baulinks.de/webplugin/2024/0925.php4', 'belegt', '2026-10-10', false, true, 'blind'),
  (8512, 18, 13, 'BE', 'Baumschutzverordnung novellieren, um den Schutzstatus von Bäumen zu stärken.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8513, 18, 13, 'BE', 'Hitzeaktionsplan jährlich evaluieren und weiterentwickeln.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8514, 18, 13, 'BE', 'Hitze- und Klimaanpassungskonzepte in Einrichtungen der Daseinsvorsorge und im öffentlichen Raum mit Trinkwasser, Verschattung und Kühlräumen.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8515, 18, 13, 'BE', 'Begrünung verbindlich in Bau- und Sanierungsprojekte integrieren; dafür geeignete Pflanzflächen identifizieren.', '{1803}', 8453, 2, 3, null, 'Per Bauordnung umsetzbar; Gründächer und -fassaden senken Oberflächentemperaturen um rund 2 °C. Dagegen: Wirkung auf die Lufttemperatur auf Straßenniveau ist gering belegt und betrifft nur Neubauten, also langsam.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=42', 'https://research.bangor.ac.uk/en/publications/how-effective-is-greening-of-urban-areas-in-reducing-human-exposu/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8516, 18, 13, 'BE', 'Straßen und öffentliche Räume in neuen Quartieren grün gestalten, mit schattenspendenden Bäumen und kühlenden Elementen.', '{1803}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=62', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8517, 18, 13, 'BE', 'Schwengelpumpen instand setzen und neu errichten, auch zur Wasserversorgung von Straßenbäumen und Stadtgrün.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=26', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8518, 18, 13, 'BE', 'Pauschales Badeverbot in der Spree abschaffen; Baden zur Abkühlung im heißen Stadtzentrum ermöglichen.', '{1803}', 8462, 1, 2, null, 'Bietet Abkühlung an heißen Tagen, besonders ohne Freibad in der Nähe. Dagegen: lindert nur Folgen, Wasserqualität und Badesicherheit erfordern Aufwand; Wirkung auf Gesundheit kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8519, 18, 13, 'BE', 'Abkopplung von der Mischwasserkanalisation deutlich voranbringen, damit Wasser in der Stadt bleibt.', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=25', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8520, 18, 13, 'BE', 'Schwammstadt: Regenwasser vor Ort halten durch Entsiegelung, begrünte Dächer, Regengärten und Versickerung; kühlt und entlastet die Kanalisation.', '{1803,1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8521, 18, 13, 'BE', 'Entsiegelungsprogramm mit Netto-Null-Ziel; jährlich mehr Entsiegelung öffentlicher Flächen.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8522, 18, 13, 'BE', 'Bürobau-Moratorium: kein weiteres Baurecht für neue Bürogebäude, damit keine weiteren Flächen versiegelt werden.', '{1804}', 8470, 1, 2, null, 'Verhindert einzelne Neuversiegelungen. Dagegen: Bürobauten sind ein kleiner Teil der Neuversiegelung, bestehendes Baurecht bleibt; die Wirkung ist nicht untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=57', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8523, 18, 13, 'BE', 'Baulücken, Brachen und überbreite Straßen nutzen; mehrgeschossig statt Flachbau, um Neuversiegelung zu begrenzen.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=57', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8524, 18, 13, 'BE', 'Neue Stadtquartiere auf den Prüfstand stellen, die ökologisch wichtige Flächen versiegeln; Planänderungen anstoßen.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=65', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8525, 18, 13, 'BE', 'Regenwasser zur Bewässerung verpflichtend machen.', '{1804}', 8469, 1, 3, null, 'Per Bauordnung oder Vorgabe leicht umsetzbar, hält etwas Regenwasser vor Ort. Dagegen: Speichervolumen ist klein, bei Starkregen ist der Speicher schnell voll; Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=25', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8526, 18, 13, 'BE', 'Regenwasseragentur ausbauen und finanziell stärken, um dezentrales Regenwassermanagement zu koordinieren.', '{1804}', 8468, 1, 3, null, 'Beratung und Koordination können den Umbau zur Schwammstadt beschleunigen und sind günstig umsetzbar. Dagegen: Die Stelle baut selbst kaum etwas, ihr eigener Beitrag zur Entsiegelung ist nicht untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=22', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8527, 18, 13, 'MV', 'Kommunale Klimaanpassungskonzepte fördern, damit Orte vor Hitze und Starkregen geschützt sind', '{1803,1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=11', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8528, 18, 13, 'MV', 'Klimaanpassung in den Kommunen stärken mit Trinkwasserspendern, klimaresilienten Baumpflanzungen und Schwammstadt-Maßnahmen, damit es im Sommer kühler bleibt', '{1803,1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=13', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8529, 18, 13, 'MV', 'Kommunen bei Klimaanpassung, Hitzevorsorge und Schutz vor Starkregen und Hochwasser stärker unterstützen', '{1805,1803,1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=11', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8530, 18, 13, 'MV', 'Naturnahe Pufferzonen an Gewässern ausbauen, damit Überflutungen abgefedert und Wasser in der Fläche gehalten wird', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://gruene-mv.de/?wpdmdl=33772#page=14', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8531, 18, 13, 'MV', 'Bundes-Bauturbo für Innenentwicklung und Nachverdichtung nutzen, um zusätzlichen Flächenverbrauch auf der grünen Wiese zu vermeiden', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8532, 18, 13, 'MV', 'Leerstand und Brachflächen kommunal managen und Zwischennutzungen fördern', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8533, 18, 13, 'ST', 'Bebauung in Überschwemmungsgebieten untersagen, um den Hochwasserschutz zu stärken', '{1805}', 8473, 3, 2, null, 'Verzicht auf Bebauung in Überschwemmungsflächen gilt Fachbehörden als wirksamste Vermeidung von Hochwasserschäden. Dagegen: Rahmen setzt das Bundesrecht (Ausnahmen im WHG), Länder können nur Planung und Ausnahmepraxis verschärfen; Bestand bleibt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=12', 'https://www.lfu.bayern.de/wasser/hw_handlungsfelder/vermeidung/index.htm', 'belegt', '2026-10-10', false, true, 'blind'),
  (8534, 18, 13, 'ST', 'Natürlichen Wasserrückhalt in der Fläche durch naturnahen Hochwasserschutz fördern und stärken', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=12', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8535, 18, 13, 'ST', 'Flussauen renaturieren und Altarme anbinden; Dämpfung von Hochwasser als Nebenwirkung', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=12', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8536, 18, 13, 'ST', 'Nicht genutzte Asphaltflächen entsiegeln und ein Entsiegelungskataster einführen', '{1804}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=9', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8537, 18, 13, 'ST', 'Bis 2050 kein weiterer Flächenverbrauch ohne gleichzeitige Entsiegelung', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8538, 18, 13, 'ST', 'Beratung zu Wohnraum-Suffizienz fördern, um den Pro-Kopf-Flächenverbrauch zu senken', '{1804}', null, 1, 3, null, 'Beratung zu kleinerem Wohnflächenbedarf ist günstig und kann Neubaubedarf etwas senken. Dagegen: Wirkung auf Versiegelung ist indirekt und kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=91', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8539, 18, 13, 'ST', 'Flächen für Neubauten nur vorsehen, wenn ÖPNV-Anbindung vorhanden ist oder sichergestellt werden kann', '{1804}', null, 1, 2, null, 'Bindet neue Bauflächen an ÖPNV-Anschluss und kann Zersiedlung bremsen. Dagegen: begrenzt nicht die Menge der Neuversiegelung, Wirkung auf Versiegelung kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=92', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8540, 18, 13, 'ST', 'Nachverdichtung mit Aufwertung und Sicherung urbaner Grünflächen verbinden', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8541, 18, 13, 'ST', 'Schwammstadt-Prinzip sowie Dach- und Fassadenbegrünung und grüne Gleise fördern', '{1803,1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8542, 18, 13, 'ST', 'Förderung von Begrünungskonzepten, baulichem Hitzeschutz und passiver Kühlung als neuer Standard', '{1803}', 8459, 2, 2, null, 'Verschattung, Nachtlüftung und passive Kühlung senken Innentemperaturen in Modellstudien deutlich. Dagegen: Nachrüstung ist teuer und dauert, bei künftig stärkerer Hitze reichen passive Maßnahmen allein teils nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8543, 18, 13, 'ST', 'Förderprogramm für Kommunen und Einrichtungen zur Stärkung des Hitzeschutzes', '{1803}', 8459, 2, 2, null, 'Verschattung, Nachtlüftung und passive Kühlung senken Innentemperaturen in Modellstudien deutlich. Dagegen: Nachrüstung ist teuer und dauert, bei künftig stärkerer Hitze reichen passive Maßnahmen allein teils nicht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=81', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8544, 18, 14, 'BE', 'Klimaresilienz der Stadt stärken, unter anderem durch Maßnahmen zur Stadtdurchlüftung und Verschattung.', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=89', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8545, 18, 14, 'BE', 'Regenwassermanagement flächendeckend anstoßen und fördern: Stauraum in der Kanalisation, vor allem dezentrales Auffangen und Versickern.', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=89', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8546, 18, 14, 'BE', 'Grün- und Erholungsflächen zwischen den Siedlungsachsen dauerhaft schützen.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=37', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8547, 18, 14, 'MV', 'Innerstädtische Grünflächen, Kleingartenanlagen und Kaltluftschneisen fördern, um sommerlicher Überhitzung vorzubeugen.', '{1803}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=32', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8548, 18, 14, 'MV', 'Fortsetzung und regelmäßige Überprüfung der Hochwasser- und Küstenschutzprogramme; Vorrang für nachweislich wirksame Maßnahmen.', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=35', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8549, 18, 14, 'MV', 'Bestehende Retentionsräume dort sichern, wo sie für den nachgewiesenen Hochwasserschutz erforderlich sind.', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=35', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8550, 18, 14, 'ST', 'Naturschutzmittel vorrangig in Städten einsetzen; extensiv gepflegte Grünflächen sollen durch Kühlung das bebaute Umfeld entlasten.', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=18', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8551, 18, 14, 'ST', 'Innenentwicklung (Ortskerne beleben, Brachflächen aktivieren) hat Vorrang vor zusätzlichem Flächenverbrauch.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8552, 18, 15, 'BE', 'Verpflichtende Entsiegelung von Flächen, wo sinnvoll und mit geringem Aufwand möglich, zusammen mit Flächensparprogrammen.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=80', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8553, 18, 15, 'BE', 'Neue Bauprojekte sollen nicht auf Grün-, Wald- oder Wasserflächen entstehen.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=80', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8554, 18, 15, 'BE', 'Anreize für private Eigentümer, ihre Flächen teilweise zu entsiegeln.', '{1804}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=80', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8555, 18, 15, 'BE', 'Abwasser- und Regenwassersysteme langfristig auf Trennsystem umstellen, damit Regen- und Abwasser getrennt fließen.', '{1804}', null, 1, 1, null, 'Ein Trennsystem verringert Mischwasserüberläufe und kann das Netz entlasten. Dagegen: Es hält kein Wasser zurück und versickert nichts, der Umbau ist sehr teuer und dauert Jahrzehnte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=81', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8556, 18, 15, 'BE', 'Nachpflanzpflicht für gefällte Bäume konsequenter durchsetzen und mit Baumbilanzen kontrollieren.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=79', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8557, 18, 15, 'BE', 'Bezirke erhalten ausreichend Mittel, qualifiziertes Personal und Pflegekonzepte für die Grünflächenpflege.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=79', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8558, 18, 15, 'BE', 'Innerstädtische Kleingartenanlagen langfristig erhalten und durch festgesetzte Bebauungspläne sichern.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=10', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8559, 18, 15, 'MV', 'Leerstände durch Förderung von Sanierung und Umbau nutzbar machen, damit neuer Wohnraum ohne zusätzliche Flächeninanspruchnahme entsteht', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=90', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8560, 18, 15, 'MV', 'Kleingarten- und Siedlungsflächen vor Bauprojekten schützen und bei der Stadt- und Regionalplanung berücksichtigen', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=93', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8561, 18, 15, 'ST', 'Mehr Überflutungsflächen schaffen, um künftige Hochwasserlagen besser zu beherrschen', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=205', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8562, 18, 15, 'ST', 'Versiegelungen und Einengungen entlang der Flussläufe abbauen', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=205', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8563, 18, 16, 'BE', 'Baulicher Hitzeschutz wird für Wohngebäude und Gebäude mit dauerhaftem Aufenthalt, etwa Pflegeheime und Krankenhäuser, verpflichtend.', '{1803}', null, 2, 2, null, 'Pflicht zu baulichem Hitzeschutz in Wohnungen, Pflegeheimen und Kliniken setzt bei Innenraumhitze an; passive Maßnahmen senken Innentemperaturen. Dagegen: Nachrüstpflicht im Bestand ist teuer und langwierig, Ausgestaltung offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', 'https://www.cibsejournal.com/cibse-news/study-tests-overheating-strategies-in-care-homes/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8564, 18, 16, 'BE', 'Straßenbaumbestand auf eine Million bis 2040 ausweiten, mit Mitteln für Pflanzung und Pflege.', '{1803}', 8454, 2, 2, null, 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8565, 18, 16, 'BE', 'Bei Neubauten wird ein verbindlicher Mindestanteil an Grünflächen vorgeschrieben, gegen Hitze und für Versickerung von Regen.', '{1803,1804}', 8453, 2, 3, null, 'Per Bauordnung umsetzbar; Gründächer und -fassaden senken Oberflächentemperaturen um rund 2 °C. Dagegen: Wirkung auf die Lufttemperatur auf Straßenniveau ist gering belegt und betrifft nur Neubauten, also langsam.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=202', 'https://research.bangor.ac.uk/en/publications/how-effective-is-greening-of-urban-areas-in-reducing-human-exposu/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8566, 18, 16, 'BE', 'Netto-Null-Versiegelung bis 2030; wo versiegelt wird, muss im Stadtgebiet in gleicher Größe entsiegelt werden.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=202', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8567, 18, 16, 'BE', 'Regenwassermanagement durch Versickerung vor Ort auch im Liegenschaftsbestand erweitern.', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=204', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8568, 18, 16, 'BE', 'Grau- und Regenwassernutzung in die Bauordnung aufnehmen.', '{1804}', 8469, 1, 3, null, 'Per Bauordnung oder Vorgabe leicht umsetzbar, hält etwas Regenwasser vor Ort. Dagegen: Speichervolumen ist klein, bei Starkregen ist der Speicher schnell voll; Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=46', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8569, 18, 16, 'BE', 'Regenwasseragentur als Beratungsstelle für den Umbau zur Schwammstadt besser ausstatten.', '{1804}', 8468, 1, 3, null, 'Beratung und Koordination können den Umbau zur Schwammstadt beschleunigen und sind günstig umsetzbar. Dagegen: Die Stelle baut selbst kaum etwas, ihr eigener Beitrag zur Entsiegelung ist nicht untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=204', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8570, 18, 16, 'BE', 'Installation von Regentonnen im öffentlichen Raum erleichtern.', '{1804}', 8469, 1, 3, null, 'Per Bauordnung oder Vorgabe leicht umsetzbar, hält etwas Regenwasser vor Ort. Dagegen: Speichervolumen ist klein, bei Starkregen ist der Speicher schnell voll; Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=204', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8571, 18, 16, 'BE', 'Stadtbäume sollen mit Regen- und aufbereitetem Grauwasser statt mit Trinkwasser bewässert werden.', '{1804}', 8469, 1, 3, null, 'Per Bauordnung oder Vorgabe leicht umsetzbar, hält etwas Regenwasser vor Ort. Dagegen: Speichervolumen ist klein, bei Starkregen ist der Speicher schnell voll; Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=204', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8572, 18, 16, 'BE', 'Bewässerung der Stadtbäume durch personell und finanziell gestärkte Ämter.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8573, 18, 16, 'BE', 'Kühle Innenräume in öffentlichen Gebäuden in jedem Kiez schaffen.', '{1803}', null, 1, 2, null, 'Kühle Räume senken Körpertemperatur und Kreislaufbelastung kurzfristig. Dagegen: Ein Rückgang der Sterblichkeit durch öffentliche Kühlräume ist nicht direkt belegt, und Gefährdete nutzen sie oft nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10234508', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8574, 18, 16, 'BE', 'Öffentliche Spielplätze, Planschen und Wasserbecken mit Sonnenschutzsegeln ausstatten.', '{1803}', 8463, 1, 3, null, 'Schatten senkt die gefühlte Temperatur vor Ort deutlich und ist günstig umsetzbar. Dagegen: wirkt nur punktuell an einzelnen Orten, Gesundheitswirkung kaum gesondert untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8575, 18, 16, 'BE', 'Tempelhofer Feld frei von Bebauung halten, als Kaltluftschneise für die Stadt.', '{1803}', 8458, 2, 3, null, 'Kaltluft aus Freiflächen entlastet überhitzte Stadtteile in heißen Nächten, Fachrichtlinien empfehlen den Erhalt von Luftleitbahnen; planerisch umsetzbar. Dagegen: wirkt nur bei windschwachen Nächten und in begrenzter Reichweite.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=52', 'https://www.baulinks.de/webplugin/2024/0925.php4', 'belegt', '2026-10-10', false, true, 'blind'),
  (8576, 18, 16, 'BE', 'Maßnahmen gegen Hitze, Lärm und Luft sowie mehr Grün in sozial benachteiligten Kiezen umsetzen.', '{1803}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=201', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8577, 18, 16, 'BE', 'Gesetzlichen Schutz für Grünflächen, Kleingärten und Friedhöfe stärken; mehr Naturflächen schaffen.', '{1803}', 8456, 2, 2, null, 'Parks und Stadtwälder kühlen ihr Umfeld nachweislich (große Parks 1 bis 2 °C, Reichweite mehrere hundert Meter). Dagegen: Flächen in dichten Städten sind knapp, Umsetzung dauert Jahre und Wirkung bleibt lokal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=201', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8578, 18, 16, 'BE', 'Nachverdichtungsvorhaben landeseigener Wohnungsbaugesellschaften in Quartieren überprüfen und bis zur Klärung aussetzen.', '{1803}', 8455, 1, 3, null, 'Erhält die belegte Kühlwirkung von Bäumen und Grün und ist mit Haushaltsmitteln und Verordnungen umsetzbar. Dagegen: sichert vor allem den Bestand und schafft kaum zusätzliche Kühlung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=50', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8579, 18, 16, 'BE', 'Kein neues Baurecht für Bürokomplexe, damit weitere Versiegelung verhindert wird.', '{1804}', 8470, 1, 2, null, 'Verhindert einzelne Neuversiegelungen. Dagegen: Bürobauten sind ein kleiner Teil der Neuversiegelung, bestehendes Baurecht bleibt; die Wirkung ist nicht untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=49', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8580, 18, 16, 'BE', 'Bei der Bauplanung Aufstockung und Umbau gegenüber flächenintensivem Neubau priorisieren.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=49', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8581, 18, 16, 'BE', 'Flächennutzungsplan überarbeiten; Netto-Null-Versiegelung ab 2030 und Schutz wertvoller Freiflächen planerisch sichern.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=44', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8582, 18, 16, 'BE', 'Beherbergungsentwicklungsplan gegen Flächenfraß durch neue Hotels.', '{1804}', null, 1, 2, null, 'Ein Steuerungsplan für Hotels kann einzelne Neuversiegelungen vermeiden. Dagegen: Hotels sind ein kleiner Teil der Flächeninanspruchnahme, die Wirkung auf Versiegelung ist nicht untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=50', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8583, 18, 16, 'BE', 'Zivilgesellschaftliches Entsiegeln fördern, um versiegelte Flächen in Grün- und Versickerungsflächen umzuwandeln.', '{1804}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=53', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8584, 18, 16, 'BE', 'Nicht mehr benötigte Verkehrsinfrastruktur rückbauen und klimaresilient nutzen.', '{1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=46', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8585, 18, 16, 'BE', 'Hitzeschutz für Landesbeschäftigte mit Hitzeschutzplänen, Beschattung, Kühlmöglichkeiten und Abkühlpausen.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=109', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8586, 18, 16, 'BE', 'Hitzeschutzkonzepte in allen Kitas.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8587, 18, 16, 'BE', 'Hitzehilfe und aufsuchende Sozialarbeit für Menschen auf der Straße stärken.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=121', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8588, 18, 16, 'BE', 'Trinkwasserspender in öffentlichen Gebäuden und mehr Trinkbrunnen im öffentlichen Raum.', '{1803}', 8461, 1, 3, null, 'Kostengünstig und schnell umsetzbar, erleichtert ausreichendes Trinken bei Hitze. Dagegen: lindert nur Folgen, eine gesundheitliche Wirkung öffentlicher Trinkbrunnen ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=151', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8589, 18, 16, 'BE', 'Baden in ohnehin genutzten Seen zulassen, um Abkühlungsmöglichkeiten in Bezirken ohne Freibad zu schaffen.', '{1803}', 8462, 1, 2, null, 'Bietet Abkühlung an heißen Tagen, besonders ohne Freibad in der Nähe. Dagegen: lindert nur Folgen, Wasserqualität und Badesicherheit erfordern Aufwand; Wirkung auf Gesundheit kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=319', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8590, 18, 16, 'BE', 'Sozialräumlich differenzierten Hitzeschutzplan mit verbindlichen Maßnahmen und Finanzierung für Einrichtungen und Quartiere.', '{1803}', 8460, 2, 3, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher; Länder können sie mit geringem Aufwand ausbauen. Dagegen: kühlen die Stadt nicht, Wirkung hängt von verbindlicher Umsetzung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=200', 'https://www.santepubliquefrance.fr/en/node/37874', 'belegt', '2026-10-10', false, true, 'blind'),
  (8591, 18, 16, 'MV', 'Innenentwicklung und Sanierung vor Neubau fördern; Städte und Dörfer als Orte mit Innenentwicklung.', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=26', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8592, 18, 16, 'MV', 'Flächensparziele und Flächenkontingente in der Raumordnung einführen.', '{1804}', 8464, 2, 2, null, 'Verbindliche Kontingente erreichten im UBA-Modellversuch mit 87 Kommunen die Flächensparziele. Dagegen: bisher nur simuliert; nicht verbindliche Landesziele wurden meist verfehlt, Umsetzung braucht Landesplanung und Jahre.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=22', 'https://www.umweltbundesamt.de/en/publikationen/modellversuch-flaechenzertifikatehandel', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8593, 18, 16, 'ST', 'Öffentliche Investitionen in mehr Stadtgrün und nachhaltiges Bauen', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=19', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8594, 18, 16, 'ST', 'Landesfonds für Entsiegelung, der Kommunen und Eigentümer beim Rückbau versiegelter Flächen unterstützt', '{1804}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=113', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8595, 18, 16, 'ST', 'Schwammstadtprinzip in Kommunen verankern und bei neuen Projekten und Sanierungen anwenden', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8596, 18, 16, 'ST', 'Regenrückhalt in der Fläche systematisch stärken', '{1804}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8597, 18, 16, 'ST', 'Landesprogramm für Hitze- und Hochwasserschutz im klimaresilienten Tourismus', '{1803,1805}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=94', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8598, 18, 16, 'ST', 'Nachnutzung und moderate Verdichtung bestehender Siedlungsflächen statt Neubau am Stadtrand unterstützen', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=85', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8599, 18, 17, 'BE', 'Baumoffensive mit fester Haushaltsfinanzierung, Priorität für Neupflanzungen und Baumpflege; Bäume gegen Hitze', '{1803}', 8454, 2, 2, null, 'Bäume kühlen nachweislich durch Schatten und Verdunstung (Studien: spürbar niedrigere Temperaturen bei mehr Baumbestand). Dagegen: Wirkung wächst erst über Jahre, Pflanzung und Bewässerung brauchen dauerhaft Geld und Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8600, 18, 17, 'BE', 'Verbindliche Begrünungspflicht für Neubauten (begrünte Dächer, Fassaden, Innenhöfe) in Berlin', '{1803}', 8453, 2, 3, null, 'Per Bauordnung umsetzbar; Gründächer und -fassaden senken Oberflächentemperaturen um rund 2 °C. Dagegen: Wirkung auf die Lufttemperatur auf Straßenniveau ist gering belegt und betrifft nur Neubauten, also langsam.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://research.bangor.ac.uk/en/publications/how-effective-is-greening-of-urban-areas-in-reducing-human-exposu/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8601, 18, 17, 'BE', 'Entsiegelung von Asphaltflächen, wo immer möglich, für Regenwasser und Schatten', '{1804,1803}', 8466, 2, 3, null, 'Unversiegelte und durchlässige Flächen verringern den Regenabfluss nachweislich und können begrünt werden; Förderung ist Landessache. Dagegen: entsiegelbare Flächen sind begrenzt, Wirkung bleibt lokal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=56', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8602, 18, 17, 'MV', 'Förderung naturnaher Küstenschutzprojekte wie Dünen und Strandaufbau', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=85', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8603, 18, 17, 'ST', 'Stadtgrün, Grünfassaden, Schattenräume und kühlende Elemente im öffentlichen Raum schaffen', '{1803}', 8457, 1, 2, null, 'Grün, Verschattung und Wasserrückhalt wirken nachweislich; die Zusage nennt aber weder Instrument noch Umfang oder Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=29', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-10', false, true, 'blind'),
  (8604, 18, 17, 'ST', 'Städte nach dem Schwammstadt-Prinzip entwickeln: Entsiegelung, Rückhalt und Versickerung statt schneller Ableitung', '{1804,1803}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8605, 18, 17, 'ST', 'Rückhaltebecken gegen Starkregen in Städten und Gemeinden', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=29', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8606, 18, 17, 'ST', 'Regenwasser soll gezielt versickern statt ausschließlich abgeleitet zu werden', '{1804}', 8467, 2, 2, null, 'Versickerung, Rückhalt und Abkopplung verringern den Abfluss nachweislich und entlasten die Kanalisation bei Starkregen. Dagegen: Umbau des Bestands ist teuer und langwierig, bei extremem Starkregen bleibt die Wirkung begrenzt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://iieta.org/journals/ijsdp/paper/10.2495/SDP-V10-N6-806-817', 'belegt', '2026-10-10', false, true, 'blind'),
  (8607, 18, 17, 'ST', 'Kommunale Boden- und Gebäudefonds sollen den Flächenverbrauch begrenzen', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=31', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8608, 18, 17, 'ST', 'Nachverdichtung statt Neubau, um Flächenverbrauch zu begrenzen', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=31', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8609, 18, 17, 'ST', 'Sanierung alter Straßen hat Vorrang vor Neuversiegelung', '{1804}', 8465, 1, 3, null, 'Brachen und Innenentwicklung bieten großes Flächenpotenzial und sind planerisch umsetzbar. Dagegen: Der Vorrang gilt schon im Baurecht, ohne verbindliche Ziele wurde der Flächenverbrauch kaum gebremst; Brachen sind oft teuer zu mobilisieren.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', 'https://www.umweltbundesamt.de/themen/boden-landwirtschaft/flaechensparen-boeden-landschaften-erhalten/flaechenrecycling-innenentwicklung', 'gemischt', '2026-10-10', false, true, 'blind'),
  (8610, 18, 17, 'ST', 'Bestehende Hochwasser-Schutzanlagen modernisieren und an das veränderte Klima anpassen', '{1805}', 8472, 2, 3, null, 'Technischer Hochwasserschutz schützt bebaute Gebiete wirksam und wird von Ländern mit Bundesmitteln bereits betrieben. Dagegen: Deiche können Risiken flussabwärts verlagern und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind'),
  (8611, 18, 17, 'ST', 'Keine neuen Baugebiete in hochwassergefährdeten Zonen', '{1805}', 8473, 3, 2, null, 'Verzicht auf Bebauung in Überschwemmungsflächen gilt Fachbehörden als wirksamste Vermeidung von Hochwasserschäden. Dagegen: Rahmen setzt das Bundesrecht (Ausnahmen im WHG), Länder können nur Planung und Ausnahmepraxis verschärfen; Bestand bleibt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.lfu.bayern.de/wasser/hw_handlungsfelder/vermeidung/index.htm', 'belegt', '2026-10-10', false, true, 'blind'),
  (8612, 18, 17, 'ST', 'Deichrückverlegungen und Renaturierung von Auen für mehr Überschwemmungsfläche', '{1805}', 8471, 2, 2, null, 'Auen und Rückhalteflächen dämpfen Hochwasserscheitel nachweislich. Dagegen: Flächenerwerb und Planung dauern viele Jahre, und die Bebauung in Überschwemmungsgebieten ändert sich dadurch nicht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=84', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-10', false, true, 'blind');

